const tools=[['Select','选择 / 移动','A',MousePointer2],['Highlight','高亮','H',Highlighter],['Underline','下划线','U',Underline],['Text','文本批注','T',null],['Ink','手写','P',Pencil],['Rectangle','矩形','R',Square],['Ellipse','椭圆','E',Circle],['Line','直线','L',Slash],['Sticky','页面便签','N',StickyNote]] as const;
