 if(active?.draft?.id===mark.id){const body=document.querySelector<HTMLTextAreaElement>('[aria-label="批注正文"]'),subtitle=document.querySelector<HTMLInputElement>('[aria-label="便签副文本"]');if(body)mark.text=body.value;if(subtitle)mark.subtitle=subtitle.value;}return mark;
