  const message=(e:{data:any})=>{const data=e.data;if(data.type==='state'){setState(data);setConnected(true);}else if(data.type==='page'){pending.current.delete(data.key);const cache=imageCache.current;cache.delete(data.key);cache.set(data.key,data.data);while(cache.size>24)cache.delete(cache.keys().next().value!);setImages(Object.fromEntries(cache));}else if(data.type==='error'){setError(data.message);clearTimeout(toastTimer.current);toastTimer.current=setTimeout(()=>setError(''),7000);}};
