  {state.tabs.length>0&&<div className="tabs-strip" role="tablist" aria-label="已打开的文档">{state.tabs.map(tab=><DocumentTab key={tab.id} tab={tab} selected={tab.id===active?.id} post={post}/>)}</div>}
  {!state.maximized&&['l','r','t','b','tl','tr','bl','br'].map(edge=><div aria-hidden="true" key={edge} className={`window-resize resize-${edge}`} onPointerDown={e=>{e.stopPropagation();post({op:'windowResize',edge});}}/>)}
