 useEffect(()=>{if(pendingDone.current===active.gestureDone){pendingDone.current=null;setLocal(null);}},[active.gestureDone]);
 useEffect(()=>()=>{cancelAnimationFrame(frame.current);},[]);
 const flushMove=()=>{cancelAnimationFrame(frame.current);frame.current=0;const data=pendingMove.current;pendingMove.current=null;if(data){setLocal(data.preview);send({op:'move',session:active.id,points:data.points});}};
